package main

import (
	"bufio"
	"fmt"
	"os"
)

func modPow(a, e, mod int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(in, &a, &b, &p, &x)

	// Precompute discrete log table for a^k mod p
	logTable := make(map[int64]int64, p)
	cur := int64(1)
	for k := int64(0); k < p-1; k++ {
		if _, ok := logTable[cur]; !ok {
			logTable[cur] = k
		}
		cur = cur * a % p
	}

	var ans int64 = 0
	for n := int64(1); n <= p; n++ {
		rhs := b * modPow(n, p-2, p) % p
		k, ok := logTable[rhs]
		if !ok {
			continue
		}
		if k >= n {
			continue
		}
		period := p - 1
		// n + t*(p-1) <= x  and  t*(p-1) ≡ k-n (mod p)
		// t ≡ (k-n) * (p-1)^(-1) (mod p)
		// Since (p-1) ≡ -1 (mod p), inverse is -1, so t ≡ n-k (mod p)
		t0 := (n - k) % p
		if t0 < 0 {
			t0 += p
		}
		first := n + t0*period
		if first > x {
			continue
		}
		maxT := (x - n) / period
		if t0 > maxT {
			continue
		}
		ans += maxT - t0 + 1
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, ans)
	out.Flush()
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

func modPow(a, e, mod int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(in, &a, &b, &p, &x)

	// Precompute inverse of a modulo p
	ainv := modPow(a%p, p-2, p)

	// Precompute powers of ainv: invPow[i] = ainv^i mod p
	invPow := make([]int64, p)
	invPow[0] = 1
	for i := int64(1); i < p; i++ {
		invPow[i] = invPow[i-1] * ainv % p
	}

	// Precompute powers of a: powA[i] = a^i mod p
	powA := make([]int64, p)
	powA[0] = 1
	for i := int64(1); i < p; i++ {
		powA[i] = powA[i-1] * (a % p) % p
	}

	// For each residue r = n mod p, compute base = r * a^r mod p
	// and count k such that base * a^{k*(p-1)} ≡ b (mod p)
	var ans int64 = 0
	for r := int64(1); r <= p; r++ {
		base := (r % p) * powA[r%p] % p
		// Need a^{k*(p-1)} ≡ b * base^{-1} (mod p)
		// Let t = b * base^{-1} mod p
		// base^{-1} = base^{p-2} mod p
		baseInv := modPow(base, p-2, p)
		t := b % p * baseInv % p

		// We need a^{k*(p-1)} = t
		// Let y = a^{p-1}. Then y^k = t.
		y := modPow(a%p, p-1, p)

		// Precompute discrete log of y: since order divides p-1, and y^{p-1} = 1
		// But we only need exponents 0..p-2. Build map from y^k to k.
		// However, doing this for each r is too slow; instead, we note:
		// a^{k*(p-1)} = (a^{p-1})^k. But a^{p-1} ≡ 1 (mod p) by Fermat.
		// So a^{k*(p-1)} ≡ 1 for all k. Thus t must be 1.
		if t != 1 {
			continue
		}

		// Count k such that n = r + k*(p-1) <= x
		if r > x {
			continue
		}
		maxK := (x - r) / (p - 1)
		ans += maxK + 1
	}

	fmt.Println(ans)
}

