	"fmt"
	"os"
)

func modPow(a, e, mod int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(in, &a, &b, &p, &x)

	// Precompute a^k mod p for k = 0..p-2
	apow := make([]int64, p-1)
	apow[0] = 1 % p
	for k := int64(1); k <= p-2; k++ {
		apow[k] = apow[k-1] * a % p
	}

	// Precompute modular inverses of 1..p-1 using Fermat
	inv := make([]int64, p)
	for i := int64(1); i < p; i++ {
		inv[i] = modPow(i, p-2, p)
	}

	var ans int64 = 0

	for k := int64(0); k <= p-2; k++ {
		ak := apow[k]
		den := ak
		if den == 0 {
			continue
		}
		// n ≡ b * (a^k)^(-1) mod p
		n0 := b * modPow(den, p-2, p) % p

		// n must be ≡ n0 mod p and n ≡ k mod (p-1)
		// Count n = n0 + t*p ≤ x with n ≡ k (mod p-1)
		// i.e., n0 + t*p ≡ k (mod p-1) => t*p ≡ k - n0 (mod p-1)
		// Let m = p-1, g = gcd(p, m) = 1 since p is prime and m = p-1
		// So inverse of p mod m exists.
		m := p - 1
		diff := (k - n0) % m
		if diff < 0 {
			diff += m
		}
		// t ≡ diff * inv(p mod m) (mod m)
		// p mod m = 1
		// so t ≡ diff (mod m)
		t0 := diff

		// n = n0 + t*p
		nStart := n0 + t0*p
		if nStart <= 0 {
			// find smallest t >= 0 such that n > 0
			// n0 + t*p > 0 => t > -n0/p
			need := (-n0)/p + 1
			if need < 0 {
				need = 0
			}
			// t = t0 + q*m, choose q so that t >= need
			if t0 < need {
				q := (need - t0 + m - 1) / m
				t0 += q * m
				nStart = n0 + t0*p
			}
		}
		if nStart < 1 {
			nStart = 1
		}
		if nStart > x {
			continue
		}
		// step in t by m => n increases by m*p
		step := m * p
		// count of terms: 1 + (x - nStart)/step
		cnt := 1 + (x-nStart)/step
		ans += cnt
	}

	fmt.Println(ans)
}

