		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(in, &a, &b, &p, &x)

	// Precompute inverses of 1..p-1 using inv[i] = (p - p/i) * inv[p%i] % p
	inv := make([]int64, p)
	inv[1] = 1
	for i := int64(2); i < p; i++ {
		inv[i] = (p - p/i) * inv[p%i] % p
	}

	// Precompute powers of a: powA[i] = a^i mod p for i=0..p-1
	powA := make([]int64, p)
	powA[0] = 1
	for i := int64(1); i < p; i++ {
		powA[i] = powA[i-1] * a % p
	}

	// Precompute inverse powers of a: invPowA[i] = a^{-i} mod p
	invA := modPow(a, p-2, p)
	invPowA := make([]int64, p)
	invPowA[0] = 1
	for i := int64(1); i < p; i++ {
		invPowA[i] = invPowA[i-1] * invA % p
	}

	// Precompute cnt[t]: number of n in [1, p-1] with n ≡ t * a^{-n} (mod p)
	cnt := make([]int64, p)
	for n := int64(1); n < p; n++ {
		t := n * powA[n] % p
		// t * a^{-n} mod p
		key := t * invPowA[n] % p
		cnt[key]++
	}

	var ans int64
	// For each residue r = n mod p, compute t = b * a^{-r} mod p
	for r := int64(0); r < p; r++ {
		t := b * invPowA[r] % p
		c := cnt[t]
		if c == 0 {
			continue
		}
		// number of n ≤ x with n ≡ r (mod p)
		if r == 0 {
			ans += c * (x / p)
		} else if x >= r {
			ans += c * (1 + (x-r)/p)
		}
	}

	out := bufio.NewWriter(os.Stdout)
	fmt.Fprintln(out, ans)
	out.Flush()
}
