import (
	"bufio"
	"fmt"
	"os"
)

func modPow(a, e, mod int64) int64 {
	res := int64(1)
	for e > 0 {
		if e&1 == 1 {
			res = res * a % mod
		}
		a = a * a % mod
		e >>= 1
	}
	return res
}

func exgcd(a, b int64) (int64, int64, int64) {
	if b == 0 {
		return 1, 0, a
	}
	x1, y1, g := exgcd(b, a%b)
	x, y := y1, x1-a/b*y1
	return x, y, g
}

func modInv(a, mod int64) int64 {
	x, _, g := exgcd(a, mod)
	if g != 1 {
		return -1
	}
	x %= mod
	if x < 0 {
		x += mod
	}
	return x
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var a, b, p, x int64
	fmt.Fscan(in, &a, &b, &p, &x)

	phi := p - 1
	a %= p
	b %= p

	// Precompute a^k mod p for k=0..p-2
	apow := make([]int64, phi)
	apow[0] = 1 % p
	for k := int64(1); k < phi; k++ {
		apow[k] = apow[k-1] * a % p
	}

	// Precompute modular inverses of apow[k]
	invApow := make([]int64, phi)
	for k := int64(0); k < phi; k++ {
		invApow[k] = modInv(apow[k], p)
	}

	var ans int64 = 0

	for k := int64(0); k < phi; k++ {
		// n * a^n ≡ b (mod p)
		// Let n = t*phi + k, then a^n = a^k, so:
		// (t*phi + k) * a^k ≡ b (mod p)
		// t*phi + k ≡ b * (a^k)^{-1} (mod p)
		// Let c = b * invApow[k] mod p
		c := b * invApow[k] % p

		// Solve phi * t ≡ c - k (mod p)
		rhs := c - k
		rhs %= p
		if rhs < 0 {
			rhs += p
		}

		// phi and p are coprime since p is prime and phi = p-1
		invPhi := modInv(phi%p, p)
		if invPhi == -1 {
			continue
		}
		t0 := rhs * invPhi % p

		// All t ≡ t0 (mod p) give solutions
		// n = t*phi + k, 1 <= n <= x
		// t >= 0, so minimal t is t0, then t = t0 + m*p
		// n = (t0 + m*p)*phi + k
		// We need n <= x
		// (t0 + m*p)*phi + k <= x
		// m <= (x - k)/phi - t0) / p
		// also n >= 1: (t0 + m*p)*phi + k >= 1, but for m>=0 and k>=0 this holds if t0*phi + k >=1

		// minimal n
		n0 := t0*phi + k
		if n0 < 1 {
			// find smallest m so that n>=1
			// (t0 + m*p)*phi + k >= 1
			// m >= (1 - k - t0*phi)/(p*phi)
			need := int64(1) - k - t0*phi
			var m0 int64
			if need <= 0 {
				m0 = 0
			} else {
				m0 = (need + p*phi - 1) / (p * phi)
			}
			n0 = (t0 + m0*p)*phi + k
			if n0 < 1 {
				continue
			}
		}
		if n0 > x {
			continue
		}
		// max m
		maxm := (x - k) / phi - t0
		if maxm < 0 {
			continue
		}
		cnt := maxm/int64(p) + 1
		ans += cnt
	}

	fmt.Println(ans)
}
